{"kind":"tool","id":"Sn09SRZVLfg","toolName":"write_file","input":{"path":"client/src/App.jsx","instructions":"Route definitions for all roles","content":"import { Routes, Route, Navigate } from 'react-router-dom';
import PublicLayout from './layouts/PublicLayout';
import DashboardLayout from './layouts/DashboardLayout';
import { ProtectedRoute, PublicOnly } from './components/guards';

/* Public pages */
import Home from './pages/Home';
import About from './pages/About';
import HowItWorks from './pages/HowItWorks';
import AvailableDonations from './pages/AvailableDonations';
import DonationDetail from './pages/DonationDetail';
import Login from './pages/Login';
import Register from './pages/Register';

/* Donor */
import DonorDashboard from './pages/donor/DonorDashboard';
import MyDonations from './pages/donor/MyDonations';
import NewDonation from './pages/donor/NewDonation';
import EditDonation from './pages/donor/EditDonation';

/* NGO */
import NgoDashboard from './pages/ngo/NgoDashboard';
import NgoBrowse from './pages/ngo/NgoBrowse';
import NgoAccepted from './pages/ngo/NgoAccepted';

/* Volunteer */
import VolunteerDashboard from './pages/volunteer/VolunteerDashboard';
import VolunteerTasks from './pages/volunteer/VolunteerTasks';
import VolunteerHistory from './pages/volunteer/VolunteerHistory';

/* Admin */
import AdminDashboard from './pages/admin/AdminDashboard';
import AdminUsers from './pages/admin/AdminUsers';
import AdminDonations from './pages/admin/AdminDonations';
import AdminReports from './pages/admin/AdminReports';

/* Sidebar definitions per role */
import {
  HeartHandshake, ListChecks, PlusCircle,
  LayoutDashboard, Search, BadgeCheck,
  MapPinned, ClipboardList, History,
  Users, Package, BarChart3,
} from 'lucide-react';

const donorLinks = [
  { to: '/donor', label: 'Overview', icon: LayoutDashboard, end: true },
  { to: '/donor/donations/new', label: 'Add Donation', icon: PlusCircle },
  { to: '/donor/donations', label: 'My Donations', icon: ListChecks },
];

const ngoLinks = [
  { to: '/ngo', label: 'Overview', icon: LayoutDashboard, end: true },
  { to: '/ngo/browse', label: 'Browse Donations', icon: Search },
  { to: '/ngo/accepted', label: 'Accepted Donations', icon: BadgeCheck },
];

const volunteerLinks = [
  { to: '/volunteer', label: 'Overview', icon: LayoutDashboard, end: true },
  { to: '/volunteer/tasks', label: 'Pickup Tasks', icon: MapPinned },
  { to: '/volunteer/history', label: 'Task History', icon: History },
];

const adminLinks = [
  { to: '/admin', label: 'Overview', icon: LayoutDashboard, end: true },
  { to: '/admin/users', label: 'User Management', icon: Users },
  { to: '/admin/donations', label: 'Donations', icon: Package },
  { to: '/admin/reports', label: 'Reports & Charts', icon: BarChart3 },
];

export default function App() {
  return (
    <Routes>
      {/* ------------------------------ Public ------------------------------ */}
      <Route element={<PublicLayout />}>
        <Route path="/" element={<Home />} />
        <Route path="/about" element={<About />} />
        <Route path="/how-it-works" element={<HowItWorks />} />
        <Route path="/donations" element={<AvailableDonations />} />
        <Route path="/donations/:id" element={<DonationDetail />} />
        <Route
          path="/login"
          element={
            <PublicOnly>
              <Login />
            </PublicOnly>
          }
        />
        <Route
          path="/register"
          element={
            <PublicOnly>
              <Register />
            </PublicOnly>
          }
        />
      </Route>

      {/* ------------------------------ Donor ------------------------------- */}
      <Route
        path="/donor"
        element={
          <ProtectedRoute roles={['DONOR']}>
            <DashboardLayout
              title="Donor Dashboard"
              subtitle="Register surplus food, track its status and manage your donations."
              links={donorLinks}
            />
          </ProtectedRoute>
        }
      >
        <Route index element={<DonorDashboard />} />
        <Route path="donations" element={<MyDonations />} />
        <Route path="donations/new" element={<NewDonation />} />
        <Route path="donations/:id/edit" element={<EditDonation />} />
      </Route>

      {/* ------------------------------- NGO -------------------------------- */}
      <Route
        path="/ngo"
        element={
          <ProtectedRoute roles={['NGO']}>
            <DashboardLayout
              title="NGO Dashboard"
              subtitle="Discover surplus food, coordinate pickups and confirm distributions."
              links={ngoLinks}
            />
          </ProtectedRoute>
        }
      >
        <Route index element={<NgoDashboard />} />
        <Route path="browse" element={<NgoBrowse />} />
        <Route path="accepted" element={<NgoAccepted />} />
      </Route>

      {/* ---------------------------- Volunteer ----------------------------- */}
      <Route
        path="/volunteer"
        element={
          <ProtectedRoute roles={['VOLUNTEER']}>
            <DashboardLayout
              title="Volunteer Dashboard"
              subtitle="Pick up accepted donations and confirm delivery to the NGO."
              links={volunteerLinks}
            />
          </ProtectedRoute>
        }
      >
        <Route index element={<VolunteerDashboard />} />
        <Route path="tasks" element={<VolunteerTasks />} />
        <Route path="history" element={<VolunteerHistory />} />
      </Route>

      {/* ------------------------------ Admin ------------------------------- */}
      <Route
        path="/admin"
        element={
          <ProtectedRoute roles={['ADMIN']}>
            <DashboardLayout
              title="Administrator Dashboard"
              subtitle="Monitor users, donations and platform activity across the system."
              links={adminLinks}
            />
          </ProtectedRoute>
        }
      >
        <Route index element={<AdminDashboard />} />
        <Route path="users" element={<AdminUsers />} />
        <Route path="donations" element={<AdminDonations />} />
        <Route path="reports" element={<AdminReports />} />
      </Route>

      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}"}}


